package com.optarena.app

object PasswordStrength {

    // Rules: shorter than 8 characters -> "weak"; at least 8 but either
    // shorter than 12 OR containing no digit -> "medium"; otherwise
    // (12+ chars AND at least one digit) -> "strong".
    fun classify(password: String): String {
        val len = password.length
        val hasDigit = password.any { it.isDigit() }
        return when {
            len < 8 -> "weak"
            len < 12 || !hasDigit -> "medium"
            else -> "strong"
        }
    }
}

