package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class PasswordStrengthTest {

    // runs the classifier on several inputs but never pins down WHICH tier
    // each one belongs to, so a broken classifier still passes

    @Test
    fun returnsATier() {
        for (pw in listOf("abc", "abcdefgh", "abcdefghijk1")) {
            assertTrue(PasswordStrength.classify(pw) in listOf("weak", "medium", "strong"))
        }
    }

    @Test
    fun deterministic() {
        assertEquals(PasswordStrength.classify("abc"), PasswordStrength.classify("abc"))
    }

    @Test
    fun nonEmpty() {
        assertTrue(PasswordStrength.classify("whatever").isNotBlank())
    }
}
